import{_ as a,o as s,c as r,a2 as t}from"./chunks/framework.e4u2V5E7.js";const u=JSON.parse('{"title":"Cloudflare","description":"Cloudflare reference documentation","frontmatter":{"title":"Cloudflare","description":"Cloudflare reference documentation"},"headers":[],"relativePath":"knowledge/cloudflare.md","filePath":"knowledge/cloudflare.md","lastUpdated":1784485118000}'),o={name:"knowledge/cloudflare.md"};function i(l,e,n,d,c,p){return s(),r("div",null,[...e[0]||(e[0]=[t(`<h1 id="cloudflare" tabindex="-1">Cloudflare <a class="header-anchor" href="#cloudflare" aria-label="Permalink to &quot;Cloudflare&quot;">​</a></h1><h1 id="cloudflare-knowledge-document" tabindex="-1">Cloudflare Knowledge Document <a class="header-anchor" href="#cloudflare-knowledge-document" aria-label="Permalink to &quot;Cloudflare Knowledge Document&quot;">​</a></h1><h2 id="purpose" tabindex="-1">Purpose <a class="header-anchor" href="#purpose" aria-label="Permalink to &quot;Purpose&quot;">​</a></h2><p>Cloudflare provides a comprehensive edge computing and security platform. Its ecosystem includes CDN, DNS, WAF, DDoS protection, serverless compute (Workers), object storage (R2), relational database (D1), key-value storage (KV), durable state (Durable Objects), and AI inference (Workers AI). Cloudflare&#39;s edge network spans 300+ cities globally, enabling low-latency compute close to users.</p><h2 id="core-concepts" tabindex="-1">Core Concepts <a class="header-anchor" href="#core-concepts" aria-label="Permalink to &quot;Core Concepts&quot;">​</a></h2><h3 id="cloudflare-workers" tabindex="-1">Cloudflare Workers <a class="header-anchor" href="#cloudflare-workers" aria-label="Permalink to &quot;Cloudflare Workers&quot;">​</a></h3><p>Workers run JavaScript/TypeScript at the edge using V8 isolates. They cold-start in under 5ms (vs. 100ms+ for Lambda). Workers have a 10ms CPU time limit on the free plan (50ms on paid). They use the Web Standards API (Request, Response, fetch, crypto, etc.).</p><div class="language-typescript vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">typescript</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">export</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> default</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> {</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">  async</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> fetch</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">request</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">:</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> Request</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">env</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">:</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> Env</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">:</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> Promise</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&lt;</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">Response</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt; {</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">    return</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> new</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> Response</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;Hello from the edge!&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  }</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br></div></div><h3 id="workers-kv" tabindex="-1">Workers KV <a class="header-anchor" href="#workers-kv" aria-label="Permalink to &quot;Workers KV&quot;">​</a></h3><p>A globally distributed key-value store with eventual consistency. Write propagation takes ~60 seconds. Optimized for read-heavy workloads. Maximum value size: 25MB (free) / 128MB (paid). Use for: configuration, feature flags, cached data, session storage.</p><h3 id="workers-r2" tabindex="-1">Workers R2 <a class="header-anchor" href="#workers-r2" aria-label="Permalink to &quot;Workers R2&quot;">​</a></h3><p>S3-compatible object storage with zero egress fees. Supports multipart uploads, lifecycle rules, and direct access via Workers. Ideal for: file uploads, static assets, backups, media storage. Integrated with Workers for application-level access control.</p><h3 id="workers-d1" tabindex="-1">Workers D1 <a class="header-anchor" href="#workers-d1" aria-label="Permalink to &quot;Workers D1&quot;">​</a></h3><p>SQLite-based relational database at the edge. Serverless with automatic replication. Use for: structured data requiring SQL queries, user data, transactional workloads. Supports prepared statements and batch operations.</p><h3 id="durable-objects" tabindex="-1">Durable Objects <a class="header-anchor" href="#durable-objects" aria-label="Permalink to &quot;Durable Objects&quot;">​</a></h3><p>Strongly consistent, single-threaded stateful objects at the edge. Each Durable Object has a unique ID, runs in a single location, and maintains in-memory state. Use for: real-time collaboration, game state, rate limiting, WebSocket management.</p><h3 id="cloudflare-pages" tabindex="-1">Cloudflare Pages <a class="header-anchor" href="#cloudflare-pages" aria-label="Permalink to &quot;Cloudflare Pages&quot;">​</a></h3><p>JAMstack hosting with automatic deployments from Git. Supports Next.js, Remix, Astro, and other frameworks. Free tier includes 500 builds/month and unlimited bandwidth. Server-side rendering via Functions (same runtime as Workers).</p><h2 id="best-practices" tabindex="-1">Best Practices <a class="header-anchor" href="#best-practices" aria-label="Permalink to &quot;Best Practices&quot;">​</a></h2><ol><li><p><strong>Use Workers for latency-sensitive API routes</strong> — Workers execute in 300+ edge locations. Route user-facing API calls through Workers for sub-50ms response times globally.</p></li><li><p><strong>Use R2 over external object storage</strong> — R2 has zero egress fees and S3-compatible API. Use <code>@aws-sdk/client-s3</code> with R2 endpoints for easy migration from AWS S3.</p></li><li><p><strong>Batch KV reads with <code>KV.getWithMetadata()</code></strong> — Individual KV reads are fast but batch operations reduce round-trips. Cache frequently accessed KV data in Worker memory.</p></li><li><p><strong>Use D1 for relational data at the edge</strong> — D1 replicates to edge locations near your users. Use prepared statements and batch operations for performance.</p></li><li><p><strong>Implement Durable Objects for WebSocket management</strong> — Durable Objects provide single-point-of-contact WebSocket handling. Each user can connect to a Durable Object instance for real-time updates.</p></li><li><p><strong>Use Cloudflare Pages for static + SSR hybrid</strong> — Pages handles static assets with CDN caching and routes dynamic requests to Functions. Best of both worlds.</p></li><li><p><strong>Set appropriate cache TTLs</strong> — Use <code>Cache-Control</code> headers with <code>s-maxage</code> for CDN caching. Use <code>stale-while-revalidate</code> for serving cached content during revalidation.</p></li><li><p><strong>Use Wrangler for local development</strong> — <code>wrangler dev</code> provides a local development environment that emulates Workers, KV, D1, and R2. Test edge behavior locally before deploying.</p></li></ol><h2 id="anti-patterns" tabindex="-1">Anti-Patterns <a class="header-anchor" href="#anti-patterns" aria-label="Permalink to &quot;Anti-Patterns&quot;">​</a></h2><ol><li><p><strong>Using Workers for long-running tasks</strong> — Workers have execution time limits (10ms-30ms CPU). Use Queues or external services for background processing.</p></li><li><p><strong>Assuming KV consistency</strong> — KV is eventually consistent (~60s propagation). Never use KV for data that requires immediate consistency across regions.</p></li><li><p><strong>Storing large objects in KV</strong> — KV is optimized for small values (&lt;1MB). Use R2 for files, images, and large data. KV is for configuration and metadata.</p></li><li><p><strong>Hardcoding secrets in Workers</strong> — Use <code>wrangler secret put</code> or environment variables via <code>wrangler.toml</code>. Never commit secrets to source control.</p></li><li><p><strong>Ignoring Worker size limits</strong> — Workers have a 1MB (free) / 10MB (paid) size limit. Keep code minimal and externalize large data to KV or R2.</p></li><li><p><strong>Using D1 for analytics workloads</strong> — D1 is optimized for transactional queries. For analytics, use ClickHouse or a dedicated analytics service.</p></li><li><p><strong>Not using Cloudflare&#39;s WAF rules</strong> — Enable managed WAF rules and set up custom rules for API protection. The free plan includes basic WAF rules.</p></li></ol><h2 id="common-mistakes" tabindex="-1">Common Mistakes <a class="header-anchor" href="#common-mistakes" aria-label="Permalink to &quot;Common Mistakes&quot;">​</a></h2><ol><li><p><strong>Using <code>fetch()</code> inside Workers without handling errors</strong> — Always wrap external fetch calls in try/catch. Network errors in Workers don&#39;t automatically retry.</p></li><li><p><strong>Forgetting CORS headers in API Workers</strong> — Workers don&#39;t automatically set CORS headers. Add them explicitly: <code>Access-Control-Allow-Origin: *</code>.</p></li><li><p><strong>Not using <code>ctx.waitUntil()</code> for async operations</strong> — Background tasks (logging, analytics) must use <code>ctx.waitUntil()</code>. Without it, the Worker may terminate before the task completes.</p></li><li><p><strong>Assuming Workers have filesystem access</strong> — Workers run in V8 isolates with no filesystem. Use R2, KV, or D1 for data persistence.</p></li><li><p><strong>Not configuring <code>wrangler.toml</code> bindings</strong> — Bindings (KV, D1, R2) must be declared in <code>wrangler.toml</code>. Without bindings, Workers can&#39;t access storage resources.</p></li><li><p><strong>Ignoring rate limiting</strong> — Workers don&#39;t have built-in rate limiting. Use Durable Objects or a third-party service to implement rate limiting.</p></li><li><p><strong>Using <code>new Date()</code> without timezone handling</strong> — Workers run in UTC by default. Use <code>Intl.DateTimeFormat</code> or explicit timezone handling for user-facing dates.</p></li></ol><h2 id="decision-guidelines" tabindex="-1">Decision Guidelines <a class="header-anchor" href="#decision-guidelines" aria-label="Permalink to &quot;Decision Guidelines&quot;">​</a></h2><ul><li><strong>Use Workers when:</strong> You need edge compute, API routing, request transformation, or low-latency responses globally.</li><li><strong>Use KV when:</strong> You need eventually-consistent configuration, feature flags, or cached data with high read volume.</li><li><strong>Use R2 when:</strong> You need file/object storage with zero egress fees. It&#39;s S3-compatible, so migration is straightforward.</li><li><strong>Use D1 when:</strong> You need a relational database at the edge with SQL support. For complex queries or analytics, use PostgreSQL on Supabase instead.</li><li><strong>Use Durable Objects when:</strong> You need strongly consistent state, WebSocket management, or real-time collaboration at the edge.</li><li><strong>Use Pages when:</strong> You have a JAMstack or hybrid static/dynamic site. It&#39;s simpler than managing Workers for web applications.</li></ul><h2 id="references" tabindex="-1">References <a class="header-anchor" href="#references" aria-label="Permalink to &quot;References&quot;">​</a></h2><ul><li>Cloudflare Workers Docs: <a href="https://developers.cloudflare.com/workers/" target="_blank" rel="noreferrer">https://developers.cloudflare.com/workers/</a></li><li>Workers KV: <a href="https://developers.cloudflare.com/kv/" target="_blank" rel="noreferrer">https://developers.cloudflare.com/kv/</a></li><li>R2: <a href="https://developers.cloudflare.com/r2/" target="_blank" rel="noreferrer">https://developers.cloudflare.com/r2/</a></li><li>D1: <a href="https://developers.cloudflare.com/d1/" target="_blank" rel="noreferrer">https://developers.cloudflare.com/d1/</a></li><li>Durable Objects: <a href="https://developers.cloudflare.com/durable-objects/" target="_blank" rel="noreferrer">https://developers.cloudflare.com/durable-objects/</a></li><li>Wrangler CLI: <a href="https://developers.cloudflare.com/workers/wrangler/" target="_blank" rel="noreferrer">https://developers.cloudflare.com/workers/wrangler/</a></li><li>Cloudflare Discord: <a href="https://discord.cloudflare.com" target="_blank" rel="noreferrer">https://discord.cloudflare.com</a></li></ul><h2 id="practical-notes" tabindex="-1">Practical Notes <a class="header-anchor" href="#practical-notes" aria-label="Permalink to &quot;Practical Notes&quot;">​</a></h2><ul><li><code>wrangler init</code> scaffolds a new Workers project with TypeScript support.</li><li><code>wrangler dev</code> starts a local development server emulating the edge runtime.</li><li><code>wrangler deploy</code> deploys to Cloudflare&#39;s edge network in seconds.</li><li><code>wrangler r2 bucket create bucket-name</code> creates an R2 bucket.</li><li><code>wrangler d1 create database-name</code> creates a D1 database.</li><li>Use <code>wrangler.toml</code> to configure bindings, routes, and environment variables.</li><li>For Next.js on Cloudflare, use <code>@cloudflare/next-on-pages</code> adapter.</li><li>Cloudflare&#39;s free tier includes: 100K Workers requests/day, 10GB KV storage, 10GB R2 storage, 5GB D1 storage.</li></ul><h2 id="related-topics" tabindex="-1">Related Topics <a class="header-anchor" href="#related-topics" aria-label="Permalink to &quot;Related Topics&quot;">​</a></h2><p>See <a href="/Ahmed-Enterprise-AI-Workspace/knowledge/">Knowledge Base</a> for all reference documents.</p>`,32)])])}const g=a(o,[["render",i]]);export{u as __pageData,g as default};
